def process(load_nifc_areas, load_usa_states) -> pd.DataFrame:
    import geopandas as gpd

    nifc_gdf = gpd.GeoDataFrame(load_nifc_areas, geometry='geometry')
    states_gdf = gpd.GeoDataFrame(load_usa_states, geometry='geometry')

    # For each NIFC area, find all states it intersects with
    results = []
    for _, nifc_row in nifc_gdf.iterrows():
        nifc_abbr = nifc_row['GACCAbbreviation']
        nifc_geom = nifc_row['geometry']

        # Find all states that intersect with this NIFC area
        intersecting_states = states_gdf[states_gdf.geometry.intersects(nifc_geom)]
        state_abbrevs = intersecting_states['adm1_name'].unique()

        for state in state_abbrevs:
            results.append({
                'NIFC_Abbreviation': nifc_abbr,
                'NIFC_Name': nifc_row['GACCName'],
                'State': state
            })

    return pd.DataFrame(results)
